#pragma once
// Planet terrain (plan §2.5 / §2.7): cube-sphere quadtree, CDLOD morphing, tiles
// generated by worker jobs in double precision and stored camera-relative.
//
//  * Tile = 65×65 grid + skirts, vertices relative to the tile centre (float).
//  * Instance = tile centre − camera (computed in double, rounded to float).
//  * One indexed draw for all tiles (vertex pulling from a tile pool buffer).
//  * A node is refined only when all four children are resident, so the selection
//    always covers the planet without holes; missing tiles are requested by priority.
#include "engine/gpu/Resources.hpp"
#include "engine/jobs/JobSystem.hpp"

#include <glm/glm.hpp>

#include <atomic>
#include <mutex>
#include <unordered_map>
#include <vector>

namespace phx {
class HeightField;

struct TerrainVertex {
    f32 pos[3];  // relative to tile centre, ECEF axes
    u32 packed;  // octahedral normal 12+12 bits | 8-bit height class
    u32 hintsA;  // unorm8: sand | cliff | talus | desert       (terrain features, biome)
    u32 hintsB;  // unorm8: forest | conifer | snow | dryness
};
static_assert(sizeof(TerrainVertex) == 24);

struct TerrainInstance {
    f32 offset[3]; // tile centre − camera
    u32 slot;
    f32 morphStart;
    f32 morphEnd;
    f32 pad[2];
};
static_assert(sizeof(TerrainInstance) == 32);

struct TerrainStats {
    u32 drawnTiles = 0;
    u32 residentTiles = 0;
    u32 pendingTiles = 0;
    u32 uploadsThisFrame = 0;
    u32 maxLevel = 0;
    u64 tilesGenerated = 0;     // cumulative
    f64 generateMsTotal = 0.0;  // cumulative worker time
    f64 updateMs = 0.0;         // render-thread time of the last update()
};

class TerrainRenderer {
public:
    static constexpr u32 kGrid = 65;
    static constexpr u32 kGridVerts = kGrid * kGrid;
    static constexpr u32 kSkirtVerts = 4 * kGrid;
    static constexpr u32 kVertsPerTile = kGridVerts + kSkirtVerts;
    static constexpr u32 kPoolSlots = 4096; // ≈ 420 MiB of tile vertices (24-byte vertices)
    static constexpr u32 kMaxInstances = 4096;
    static constexpr u32 kMaxLevel = 18;
    static constexpr u32 kGroundMaterials = 9;          // ≈ 76 m tiles, 1.2 m vertex spacing
    static constexpr u32 kUploadsPerFrame = 48;


    TerrainRenderer(VulkanContext& ctx, Bindless& bindless, jobs::JobSystem& jobs, const HeightField& heights,
                    u32 framesInFlight, VkFormat colorFormat, VkFormat depthFormat);
    ~TerrainRenderer();

    // Render thread, once per frame before recording.
    void update(u32 slot, const glm::dvec3& cameraEcef, const glm::mat4& viewProjEcef, f32 fovY, u32 viewportHeight,
                u64 frameNumber);
    void recordUploads(VkCommandBuffer cmd, u32 slot); // outside a render pass
    void recordDraw(VkCommandBuffer cmd, u64 frameAddr, u32 slot);
    [[nodiscard]] const TerrainStats& stats() const { return stats_; }

private:
    struct Tile {
        u32 slot = ~0u;
        bool ready = false;
        glm::dvec3 center{};
        f64 radius = 0;
        u64 lastUsed = 0;
    };
    struct Request {
        u64 key;
        u32 slot;
        glm::dvec3 center;
        f64 radius;
        std::vector<TerrainVertex> vertices;
    };
    struct Candidate {
        u64 key;
        f64 priority;
    };

    void generate(Request& r) const;
    void select(u64 key, const glm::dvec3& cam, u64 frame);
    bool ensureRequested(u64 key, f64 priority);
    void prepareEviction(u64 frame, u32 needed);
    u32 allocateSlot();
    void collectFinished();

    VulkanContext& ctx_;
    Bindless& bindless_;
    jobs::JobSystem& jobs_;
    const HeightField& heights_;

    VkPipeline pipeline_ = VK_NULL_HANDLE;
    Image groundTextures_[kGroundMaterials][3]{};
    Buffer pool_;
    Buffer indices_;
    u32 indexCount_ = 0;
    std::vector<Buffer> instanceBuffers_;
    std::vector<Buffer> staging_;
    std::vector<std::pair<u32, u32>> pendingCopies_; // (staging index, pool slot) for this frame

    std::unordered_map<u64, Tile> tiles_;
    std::vector<u32> freeSlots_;
    std::vector<std::pair<u64, u64>> evictable_; // (lastUsed, key), oldest last
    std::vector<Candidate> wanted_;
    std::vector<TerrainInstance> instances_;
    std::vector<Request*> readyForUpload_;
    std::mutex doneMutex_;
    std::vector<Request*> done_;
    u32 inFlight_ = 0;
    u32 maxInFlight_ = 8; // worker count − 2: keeps hardware threads free for render/supervisor
    std::atomic<u64> generated_{0};
    std::atomic<u64> generateNs_{0};

    // Per-frame selection parameters
    glm::vec4 frustum_[4]{};
    f64 splitFactor_ = 4.0;
    u32 maxLevel_ = kMaxLevel;
    TerrainStats stats_;
};

} // namespace phx
